package com.smarthrms.service;
import com.smarthrms.dto.DashboardDtos.*; import com.smarthrms.entity.EmployeeStatus; import com.smarthrms.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.math.*; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
@Service @RequiredArgsConstructor @org.springframework.transaction.annotation.Transactional(readOnly=true) public class DashboardService { private final EmployeeRepository employees; private final DepartmentRepository departments; public Stats stats(){var all=employees.findAll(); long total=all.size(),active=all.stream().filter(e->e.getStatus()==EmployeeStatus.ACTIVE).count(); BigDecimal avg=all.stream().map(e->e.getSalary()).reduce(BigDecimal.ZERO,BigDecimal::add); if(total>0)avg=avg.divide(BigDecimal.valueOf(total),2,RoundingMode.HALF_UP); BigDecimal high=all.stream().map(e->e.getSalary()).max(BigDecimal::compareTo).orElse(BigDecimal.ZERO); var recent=all.stream().sorted(Comparator.comparing(com.smarthrms.entity.Employee::getJoiningDate).reversed()).limit(5).map(e->new RecentEmployee(e.getId(),e.getFirstName()+" "+e.getLastName(),e.getProfession(),e.getDepartment().getName(),label(e.getJoiningDate()))).toList(); var dist=departments.findAll().stream().map(d->{long c=d.getEmployees().size();double p=total==0?0:(c*100.0/total);return new DepartmentStat(d.getName(),c,Math.round(p*10)/10.0);}).toList(); return new Stats(total,departments.count(),active,avg,high,recent,dist);} private String label(LocalDate d){long days=Math.max(0,ChronoUnit.DAYS.between(d,LocalDate.now()));return days==0?"Today":days+" days ago";} }
